// WHAT THIS DOES
// Sends Mira's answer back, whichever path produced it (an agent or Clarify).
// "Build Langfuse trace" already worked out the answer.
// It adds a note at the end when:
//   - the report was saved as a Google Doc (by "Save Doc") -> the Doc link
//   - a stakeholder draft was sent for approval (by "Send for approval", chat runs only)
// EVAL MODE: the evaluation workflow also needs the tool results ("context"),
// which agent answered ("path") and the Orchestrator's intent. They are returned as
// extra fields; the chat window only shows "output".

// Step 1: read the answer and details that "Build Langfuse trace" worked out
const trace = $('Build Langfuse trace').first().json;
const request = $('Normalize request').first().json;
let answer = trace.answer;

// Step 2: helper - did this node run in this request?
function nodeRan(nodeName) {
  try {
    return $(nodeName).isExecuted;
  } catch (error) {
    return false;
  }
}

// Step 3: if a Google Doc was saved, add its link
if (nodeRan('Save Doc')) {
  const docLink = $('Save Doc').first().json.webViewLink || '';
  if (docLink !== '') {
    answer = answer + '\n\n---\n**Saved to Google Doc:** ' + docLink;
  }
}

// Step 4: if a stakeholder draft was sent for approval (not in eval mode), say where
if (nodeRan('Send for approval') && request.source !== 'eval') {
  answer = answer + '\n\n---\n**Sent to Slack (#mira-reports) for your approval.** It will be emailed only after you click Approve.';
}

// Step 5: send it back (chat shows "output"; the evaluation also reads the other fields)
return [{
  json: {
    output: answer,
    context: trace.context,
    path: trace.path,
    intent: $('Orchestrator').first().json.output.intent,
    test_id: request.test_id
  }
}];

// WHAT THIS DOES
// Runs when the Orchestrator decides there isn't enough information.
// Instead of guessing, Mira asks the user for what is missing.
//   - If the Orchestrator couldn't tell what kind of request it was ("unclear"),
//     Mira asks which kind of output the user wants.
//   - Otherwise Mira lists the missing details (e.g. scope, timeline, team).
// (Known issue T9: see implementation_plan.md. Left as-is until after the baseline run.)

// Step 1: read the Orchestrator's decision
const decision = $('Orchestrator').first().json.output;
const missingItems = decision.missing || [];

// Step 2: choose the message
let message = '';
if (decision.intent === 'unclear') {
  message = "I'm not sure what you need. Do you want a project plan, a risk assessment, a status report, or a stakeholder update?";
} else {
  message = "I don't have enough information to do that yet. Please tell me: " + missingItems.join(', ') + '.';
}

// Step 3: send the message back to the chat
return [{ json: { output: message } }];

// WHAT THIS DOES
// Builds one Langfuse trace for a Mira request, for WHICHEVER path ran:
// an agent (Planner, Risk, Status, Stakeholder) or Clarify (vague request).
// The trace reads top to bottom, in the order things happened:
//   mira (the whole request)
//     1. Orchestrator   - the routing decision (runs on every request)
//     2. Agent          - the agent's model call (skipped for Clarify)
//          - tool calls  - one entry per tool, shown UNDER the agent that called it
// Token counts are ESTIMATED from text length (PRD §5.2); Langfuse turns them into cost.
// Calibrated on T1: agent estimate 3,108 tokens vs n8n's own count 3,098.
// Timing: n8n doesn't give us real step times here, so each step gets its own
// time slot inside a 1-second window. This keeps the steps in the right order in Langfuse.

// Step 1: settings
const modelName = 'gpt-4o-mini';
const agentNames = ['Planner', 'Risk', 'Status', 'Stakeholder'];
const orchestratorPromptTokens = 600; // Orchestrator system prompt, sent on every request
const systemPromptTokens = 300;       // agent system prompt + tool definitions, sent on every model call
const tokensPerToolCall = 20;         // tokens the model writes to ask for one tool
const charsPerTokenIn = 4;            // input text: about 4 characters per token
const charsPerTokenOut = 4.5;         // Markdown answers: about 4.5 characters per token

// Step 2: helpers
function asText(value) {
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value || '');
}
function inputTokens(text) {
  return Math.ceil(String(text || '').length / charsPerTokenIn);
}
function outputTokens(text) {
  return Math.ceil(String(text || '').length / charsPerTokenOut);
}
function nodeRan(nodeName) {
  // True if this node ran in this request. A node that doesn't exist yet counts as "didn't run".
  try {
    return $(nodeName).isExecuted;
  } catch (error) {
    return false;
  }
}

// Step 3: get the request (from "Normalize request": chat or schedule) and the Orchestrator's decision
const request = $('Normalize request').first().json;
const userMessage = request.message || '';
const sessionId = request.session_id || 'no-session';
const source = request.source || 'chat';
const testId = request.test_id || '';
const decision = $('Orchestrator').first().json.output;

// Step 4: find which path ran and get its answer
let pathName = 'Clarify';
let answer = '';
let toolCalls = [];
for (const name of agentNames) {
  if (nodeRan(name)) {
    pathName = name;
    break;
  }
}
if (pathName === 'Clarify') {
  answer = $('Clarify').first().json.output || '';
} else {
  const agentResult = $(pathName).first().json;
  answer = agentResult.output || '';
  toolCalls = agentResult.intermediateSteps || [];
}

// Step 5: estimate the tokens
// 5a. Orchestrator: one model call (its prompt + the message in, a small JSON decision out)
const orchestratorIn = orchestratorPromptTokens + inputTokens(userMessage);
const orchestratorOut = outputTokens(JSON.stringify(decision));

// 5b. Agent: 2 model calls when it uses tools (ask for tools, then write the answer), else 1
let agentModelCalls = 0;
let agentIn = 0;
let agentOut = 0;
if (pathName !== 'Clarify') {
  agentModelCalls = 1;
  if (toolCalls.length > 0) {
    agentModelCalls = 2;
  }
  let toolResultTokens = 0;
  for (const call of toolCalls) {
    toolResultTokens = toolResultTokens + inputTokens(asText(call.observation));
  }
  agentIn = agentModelCalls * (systemPromptTokens + inputTokens(userMessage)) + toolResultTokens;
  agentOut = outputTokens(answer) + toolCalls.length * tokensPerToolCall;
}

// Step 6: helpers for the OpenTelemetry format
function randomHex(length) {
  let result = '';
  for (let i = 0; i < length; i++) {
    result = result + Math.floor(Math.random() * 16).toString(16);
  }
  return result;
}
function textField(key, value) {
  return { key: key, value: { stringValue: String(value) } };
}
function numberField(key, value) {
  return { key: key, value: { intValue: Number(value) } };
}

// Time slots: the trace covers the last 1 second (1000 ms).
//   Orchestrator: 0–200 ms
//   Agent:        200–1000 ms, with its tool calls one after another inside 250–750 ms
const windowStart = (BigInt(Date.now()) - 1000n) * 1000000n;   // 1 second ago, in nanoseconds
function timeAt(milliseconds) {
  return (windowStart + BigInt(Math.round(milliseconds)) * 1000000n).toString();
}

const traceId = randomHex(32);
const rootSpanId = randomHex(16);
const agentSpanId = randomHex(16);

// Step 7: build the trace pieces ("spans")
const spans = [];

// 7a. The whole request (0–1000 ms)
spans.push({
  traceId: traceId, spanId: rootSpanId, name: 'mira', kind: 1,
  startTimeUnixNano: timeAt(0), endTimeUnixNano: timeAt(1000),
  attributes: [
    textField('langfuse.trace.name', 'mira'),
    textField('langfuse.trace.input', userMessage),
    textField('langfuse.trace.output', answer),
    textField('langfuse.session.id', sessionId),
    textField('langfuse.trace.metadata.intent', decision.intent),
    textField('langfuse.trace.metadata.sufficient', decision.sufficient),
    textField('langfuse.trace.metadata.path', pathName),
    textField('langfuse.trace.metadata.source', source),
    textField('langfuse.trace.metadata.test_id', testId),
    { key: 'langfuse.trace.tags', value: { arrayValue: { values: [
      { stringValue: 'mira' },
      { stringValue: pathName.toLowerCase() },
      { stringValue: source },
      { stringValue: testId || 'no-test' }
    ] } } }
  ]
});

// 7b. Step 1 of the request: the Orchestrator's model call (0–200 ms)
spans.push({
  traceId: traceId, spanId: randomHex(16), parentSpanId: rootSpanId, name: 'Orchestrator', kind: 1,
  startTimeUnixNano: timeAt(0), endTimeUnixNano: timeAt(200),
  attributes: [
    textField('langfuse.observation.type', 'generation'),
    textField('gen_ai.request.model', modelName),
    textField('langfuse.observation.input', userMessage),
    textField('langfuse.observation.output', JSON.stringify(decision)),
    numberField('gen_ai.usage.input_tokens', orchestratorIn),
    numberField('gen_ai.usage.output_tokens', orchestratorOut),
    textField('langfuse.observation.metadata.token_counts', 'estimated from text length')
  ]
});

// 7c. Step 2 of the request: the agent's model call (200–1000 ms; skipped for Clarify)
if (pathName !== 'Clarify') {
  spans.push({
    traceId: traceId, spanId: agentSpanId, parentSpanId: rootSpanId, name: pathName, kind: 1,
    startTimeUnixNano: timeAt(200), endTimeUnixNano: timeAt(1000),
    attributes: [
      textField('langfuse.observation.type', 'generation'),
      textField('gen_ai.request.model', modelName),
      textField('langfuse.observation.input', userMessage),
      textField('langfuse.observation.output', answer),
      numberField('gen_ai.usage.input_tokens', agentIn),
      numberField('gen_ai.usage.output_tokens', agentOut),
      textField('langfuse.observation.metadata.token_counts', 'estimated from text length'),
      numberField('langfuse.observation.metadata.model_calls', agentModelCalls)
    ]
  });

  // 7d. The agent's tool calls, shown under the agent, one after another (250–750 ms)
  let slotLength = 500;
  if (toolCalls.length > 0) {
    slotLength = 500 / toolCalls.length;
  }
  let slotStart = 250;
  for (const call of toolCalls) {
    let toolName = 'tool';
    let toolInput = '';
    if (call.action) {
      toolName = call.action.tool || 'tool';
      toolInput = asText(call.action.toolInput);
    }
    spans.push({
      traceId: traceId, spanId: randomHex(16), parentSpanId: agentSpanId, name: toolName, kind: 1,
      startTimeUnixNano: timeAt(slotStart), endTimeUnixNano: timeAt(slotStart + slotLength - 10),
      attributes: [
        textField('langfuse.observation.type', 'span'),
        textField('langfuse.observation.input', toolInput),
        textField('langfuse.observation.output', asText(call.observation).slice(0, 5000))
      ]
    });
    slotStart = slotStart + slotLength;
  }
}

// Step 8: the tool results as one text block ("context"). The evaluation's Groundedness
// judge checks Mira's answer against exactly this: what the tools returned.
let context = '';
for (const call of toolCalls) {
  let toolName = 'tool';
  if (call.action) {
    toolName = call.action.tool || 'tool';
  }
  context = context + '[' + toolName + ']\n' + asText(call.observation) + '\n\n';
}
if (context === '') {
  context = 'No tools were called.';
}

// Step 9: wrap everything in the OpenTelemetry envelope and send it on
const payload = {
  resourceSpans: [{
    resource: { attributes: [textField('service.name', 'mira')] },
    scopeSpans: [{ scope: { name: 'n8n' }, spans: spans }]
  }]
};

return [{
  json: {
    path: pathName,
    answer: answer,
    context: context,
    estimate: {
      orchestratorTokens: orchestratorIn + orchestratorOut,
      agentTokens: agentIn + agentOut,
      total: orchestratorIn + orchestratorOut + agentIn + agentOut
    },
    payload: payload
  }
}];

// WHAT THIS DOES
// Gets the report ready to save as a Google Doc: a title and the text.
// The title says what kind of report it is and when it was made.

// Step 1: which agent answered, and its answer (worked out by "Build Langfuse trace")
const trace = $('Build Langfuse trace').first().json;
const agentName = trace.path;
const reportText = trace.answer;

// Step 2: pick the report type from the agent
let reportType = 'Report';
if (agentName === 'Planner') {
  reportType = 'Project plan (DRAFT)';
} else if (agentName === 'Risk') {
  reportType = 'Risk assessment';
} else if (agentName === 'Status') {
  reportType = 'Weekly status report';
}

// Step 3: the date and time it was made, e.g. "2026-10-25 14:03"
const madeAt = new Date().toISOString().slice(0, 16).replace('T', ' ');

// Step 4: send on the title and text
return [{
  json: {
    title: 'Mira — ' + reportType + ' — ' + madeAt,
    text: reportText
  }
}];

// WHAT THIS DOES
// Mira main has three ways in:
//   - the chat (a person asks)                       -> source "chat"
//   - the Monday schedule                            -> source "schedule"
//   - the evaluation workflow (runs the 13 tests)    -> source "eval"
// This node gives all three the same shape, so every node after it works the same way:
//   message    = the request text
//   session_id = groups messages in Langfuse
//   source     = "chat", "schedule" or "eval" (decides how the answer is delivered)
//   test_id    = the test number (eval runs only, e.g. "T5"), shown in Langfuse
// All later nodes read the request from HERE, never from a trigger.

// Step 1: the request the schedule sends every Monday.
// "the task board" tells the Orchestrator the request is about the stored project data;
// the Status agent then uses current_sprint from mira_config.json.
const scheduledMessage = 'Generate the weekly status report for the current sprint using the task board.';

// Step 2: helper - did this trigger start this run?
function triggerRan(nodeName) {
  try {
    return $(nodeName).isExecuted;
  } catch (error) {
    return false;
  }
}

// Step 3: build the request
let message = '';
let sessionId = '';
let source = '';
let testId = '';

if (triggerRan('When chat message received')) {
  const chat = $('When chat message received').first().json;
  message = chat.chatInput || '';
  sessionId = chat.sessionId || 'no-session';
  source = 'chat';
} else if (triggerRan('When Executed by Another Workflow')) {
  const evalRequest = $('When Executed by Another Workflow').first().json;
  message = evalRequest.message || '';
  testId = evalRequest.test_id || '';
  sessionId = 'eval-' + new Date().toISOString().slice(0, 10);
  source = 'eval';
} else {
  message = scheduledMessage;
  sessionId = 'schedule-' + new Date().toISOString().slice(0, 10);
  source = 'schedule';
}

// Step 4: pass it on to the Orchestrator
return [{ json: { message: message, session_id: sessionId, source: source, test_id: testId } }];

// WHAT THIS DOES
// For the scheduled Monday report only: builds a short Slack message with
// the report's title line, its Health line, and the link to the Google Doc.

// Step 1: the report text and the Doc link
const report = $('Build Langfuse trace').first().json.answer || '';
let docLink = '';
try {
  if ($('Save Doc (schedule)').isExecuted) {
    docLink = $('Save Doc (schedule)').first().json.webViewLink || '';
  }
} catch (error) {
  docLink = '';
}

// Step 2: pick out the title line and the Health line from the report
let titleLine = 'Weekly status report';
let healthLine = '';
for (const rawLine of report.split('\n')) {
  const line = rawLine.replace(/#/g, '').trim();
  if (line === '') {
    continue;
  }
  if (titleLine === 'Weekly status report' && line.toLowerCase().startsWith('status report')) {
    titleLine = line;
  }
  if (healthLine === '' && line.toLowerCase().startsWith('health')) {
    healthLine = line;
  }
}

// Step 3: build the message
let text = ':bar_chart: *' + titleLine + '*\n';
if (healthLine !== '') {
  text = text + healthLine + '\n';
}
if (docLink !== '') {
  text = text + 'Full report: ' + docLink;
} else {
  text = text + '(The Google Doc could not be saved. See the n8n execution.)';
}

// Step 4: send it on to the Slack node
return [{ json: { text: text } }];

// WHAT THIS DOES
// Decides how Mira's answer is delivered. It picks exactly ONE lane:
//   schedule  = the Monday trigger started this run -> save a Doc and post to Slack
//   doc       = a full plan, risk assessment or weekly report (Orchestrator save_to_doc = true)
//               -> save a Doc and reply in chat with the link
//   chat_only = everything else (short answers, Clarify, stakeholder drafts) -> reply in chat
// EVAL MODE: when the evaluation workflow runs a test (source = "eval"), the answer
// is always "chat_only", so 13 test runs don't create Docs or Slack posts.
// The "Delivery" Switch after this node routes on the field "lane".

// Step 1: where the request came from, what the Orchestrator decided, and which path answered
const source = $('Normalize request').first().json.source;
const decision = $('Orchestrator').first().json.output;
const path = $('Build Langfuse trace').first().json.path;

// Step 2: pick the lane
let lane = 'chat_only';
if (source === 'eval') {
  lane = 'chat_only';
} else if (source === 'schedule') {
  lane = 'schedule';
} else if (decision.save_to_doc === true && path !== 'Clarify') {
  lane = 'doc';
}

// Step 3: pass the lane on to the Switch
return [{ json: { lane: lane } }];

// WHAT THIS DOES
// Gets the report ready to save as a Google Doc: a title and the text.
// The title says what kind of report it is and when it was made.

// Step 1: which agent answered, and its answer (worked out by "Build Langfuse trace")
const trace = $('Build Langfuse trace').first().json;
const agentName = trace.path;
const reportText = trace.answer;

// Step 2: pick the report type from the agent
let reportType = 'Report';
if (agentName === 'Planner') {
  reportType = 'Project plan (DRAFT)';
} else if (agentName === 'Risk') {
  reportType = 'Risk assessment';
} else if (agentName === 'Status') {
  reportType = 'Weekly status report';
}

// Step 3: the date and time it was made, e.g. "2026-10-25 14:03"
const madeAt = new Date().toISOString().slice(0, 16).replace('T', ' ');

// Step 4: send on the title and text
return [{
  json: {
    title: 'Mira — ' + reportType + ' — ' + madeAt,
    text: reportText
  }
}];
